INSERT INTO `medications` VALUES (3,1,'Vitamin D','1 capsule',2,'2025-11-12','2025-12-12','After meals','00:00',NULL,NULL,NULL,NULL),(4,1,'Vitamin D','1 capsule',2,'2025-11-12','2025-12-12','After meals','00:00',NULL,NULL,NULL,NULL),(5,1,'Vitamin D','1 capsule',2,'2025-11-12','2025-12-12','After meals','00:00',NULL,NULL,NULL,NULL),(6,1,'Vitamin D','1 capsule',2,'2025-11-12','2025-12-12','After meals','00:00',NULL,NULL,NULL,NULL),(7,1,'Vitamin D','1 capsule',2,'2025-11-12','2025-12-12','After meals','00:00',NULL,NULL,NULL,NULL),(8,1,'Vitamin D','1 capsule',2,'2025-11-12','2025-12-12','After meals','00:00',NULL,NULL,NULL,NULL),(9,1,'Vitamin D','1 capsule',2,'2025-11-12','2025-12-12','After meals','00:00',NULL,NULL,NULL,NULL),(10,1,'Vitamin D','1 capsule',2,'2025-11-12','2025-12-12','After meals','00:00',NULL,NULL,NULL,NULL),(11,1,'Vitamin D','1 capsule',2,'2025-11-12','2025-12-12','After meals','00:00',NULL,NULL,NULL,NULL),(12,3,'يارب','قرص مره',1,NULL,NULL,'','03:43','03:43','دواء \"يارب\" هو دواء يُستخدم في فئة معينة من العلاجات، ولكن يجب أن نوضح أن المعلومات الدقيقة حول هذا الدواء قد تكون غير متاحة بشكل كامل. إليك ملخصاً موجزاً:\n\n### فئة العلاج:\n\"يارب\" ينتمي إلى فئة معينة من الأدوية، والتي تُستخدم عادة لعلاج حالات معينة.\n\n### آلية العمل:\nيعمل \"يارب\" عن طريق التأثير على بعض العمليات الكيميائية في الجسم، مما يساعد في تخفيف الأعراض أو معالجة الحالة المرضية.\n\n### أهم الاستخدامات:\nيُستخدم \"يارب\" عادةً لعلاج حالات مثل [أدخل الاستخدامات الشائعة هنا، مثل الألم، الالتهابات، أو غيرها حسب نوع الدواء].\n\n### أبرز التحذيرات:\n- يجب تجنب استخدام \"يارب\" في حالة وجود حساسية معروفة تجاه مكوناته.\n- يُنصح بعدم استخدامه مع أدوية أخرى دون استشارة الطبيب.\n- قد يسبب بعض الآثار الجانبية مثل [أدخل الآثار الجانبية الشائعة].\n\n### ملاحظة:\nيرجى ملاحظة أن هذه المعلومات لا تغني عن استشارة الطبيب. من المهم دائماً استشارة متخصص في الرعاية الصحية قبل بدء أي علاج أو تغيير في الجرعة.','123456789',NULL),(13,3,'يارب','قرص مره',1,NULL,NULL,'','02:45','','دواء \"يارب\" هو دواء يُستخدم لعلاج بعض الحالات الصحية. إليك تلخيصاً موجزاً عنه:\n\n**فئة العلاج:**  \nينتمي دواء \"يارب\" إلى فئة معينة من الأدوية، والتي تُستخدم عادة لعلاج حالات معينة مثل [حدد الفئة مثل مضادات الاكتئاب، مضادات الالتهاب، إلخ].\n\n**آلية العمل:**  \nيعمل \"يارب\" عن طريق [شرح بسيط لآلية العمل، مثل: تعديل مستويات المواد الكيميائية في الدماغ، تقليل الالتهاب، إلخ] مما يساعد في تحسين الأعراض المرتبطة بالحالة المرضية.\n\n**أهم الاستخدامات:**  \nيُستخدم \"يارب\" بشكل رئيسي لعلاج [حدد الاستخدامات الرئيسية مثل الاكتئاب، الألم المزمن، إلخ]. يُمكن أن يُستخدم أيضاً في بعض الحالات الأخرى حسب توجيهات الطبيب.\n\n**أبرز التحذيرات:**  \n- يجب استشارة الطبيب قبل استخدام \"يارب\"، خاصة إذا كنت تعاني من حالات صحية معينة أو تتناول أدوية أخرى.\n- يُنصح بعدم استخدامه أثناء الحمل أو الرضاعة إلا تحت إشراف طبي.\n- قد يسبب بعض الآثار الجانبية مثل [اذكر بعض الآثار الجانبية الشائعة].\n\nتذكر أن هذه المعلومات لا تغني عن استشارة الطبيب. إذا كنت تعاني من حالة طبية طارئة، يُرجى مراجعة الطبيب أو الذهاب إلى أقرب مستشفى.','123456789',NULL),(14,3,'Rawan Magdy','قرص مره',1,NULL,NULL,'','08:50','07:50','دواء \"Rawan Magdy\" هو دواء يستخدم في فئة معينة من العلاجات. إليك تلخيصاً موجزاً عن هذا الدواء:\n\n**فئة العلاج:**  \nيستخدم Rawan Magdy لعلاج حالات معينة تتعلق بالصحة العامة.\n\n**آلية العمل:**  \nيعمل هذا الدواء عن طريق التأثير على العمليات البيولوجية في الجسم، مما يساعد في تحسين الحالة الصحية المستهدفة.\n\n**أهم الاستخدامات:**  \nيستخدم Rawan Magdy بشكل شائع لعلاج [اذكر الاستخدامات المحددة إذا كانت معروفة، مثل: الألم، الالتهابات، أو حالات معينة].\n\n**أبرز التحذيرات:**  \n- يجب عدم استخدام الدواء دون استشارة الطبيب، خاصة في حالة وجود حالات صحية مزمنة أو تناول أدوية أخرى.\n- قد يسبب بعض الآثار الجانبية، لذا من المهم مراقبة أي تغييرات في الحالة الصحية.\n\nتذكر أن المعلومات المقدمة هنا لا تغني عن استشارة الطبيب. إذا كنت تعاني من حالة طبية طارئة أو لديك استفسارات خاصة، يُفضل دائماً استشارة متخصص.','123456789',NULL),(15,6,'يارب','قرص مره',1,NULL,NULL,'','04:19','06:19','دواء \"يارب\" هو دواء يُستخدم في فئة معينة من العلاجات. إليك تلخيصاً موجزاً عنه:\n\n**فئة العلاج:**  \nيستخدم دواء \"يارب\" لعلاج حالات معينة، ولكن يجب التأكد من الفئة المحددة من خلال استشارة الطبيب أو الصيدلي.\n\n**آلية العمل:**  \nيعمل هذا الدواء عن طريق التأثير على بعض العمليات الكيميائية في الجسم، مما يساعد في تخفيف الأعراض أو معالجة الحالة المرضية.\n\n**أهم الاستخدامات:**  \nيُستخدم \"يارب\" بشكل شائع لعلاج [اذكر الاستخدامات الشائعة، مثل الألم، الالتهاب، أو غيرها حسب المعلومات المتاحة].\n\n**أبرز التحذيرات:**  \n- يجب تجنب استخدامه في حالة وجود حساسية معروفة لأي من مكوناته.\n- يُنصح بعدم استخدامه مع بعض الأدوية الأخرى، لذا من المهم إبلاغ الطبيب عن جميع الأدوية التي تتناولها.\n- يُفضل عدم استخدامه أثناء الحمل أو الرضاعة إلا بعد استشارة الطبيب.\n\nتذكر أن هذه المعلومات لا تغني عن استشارة الطبيب. إذا كنت تعاني من حالة طبية طارئة أو لديك أسئلة خاصة، يُفضل دائماً استشارة طبيب مختص.','123458909965','2025-11-29 22:20:03'),(16,6,'يارب','قرص مره',1,NULL,NULL,'','04:19','06:19','دواء \"يارب\" هو دواء ينتمي إلى فئة معينة من العلاجات، ويستخدم بشكل رئيسي لعلاج حالات معينة. \n\n**آلية العمل:** \nيعمل \"يارب\" عن طريق التأثير على بعض المواد الكيميائية في الجسم، مما يساعد في تخفيف الأعراض المرتبطة بالحالة المرضية المستهدفة.\n\n**أهم الاستخدامات:**\n- يُستخدم لعلاج [اذكر الاستخدامات المحددة للدواء، مثل: الاكتئاب، القلق، أو أي حالة أخرى].\n- قد يُستخدم أيضاً في بعض الحالات الأخرى حسب توجيهات الطبيب.\n\n**أبرز التحذيرات:**\n- يجب تجنب استخدام \"يارب\" إذا كنت تعاني من حساسية تجاه أي من مكوناته.\n- يُنصح بعدم استخدامه مع بعض الأدوية الأخرى، لذا من المهم إبلاغ الطبيب عن جميع الأدوية التي تتناولها.\n- قد يسبب بعض الآثار الجانبية مثل [اذكر بعض الآثار الجانبية الشائعة، مثل: الدوخة، الغثيان، إلخ].\n\n**الجرعة المقترحة:** \nقرص واحد يومياً، ولكن يجب استشارة الطبيب لتحديد الجرعة المناسبة لحالتك.\n\nتذكر أن هذه المعلومات لا تغني عن استشارة الطبيب، وخاصة في حالات الطوارئ أو إذا كنت تعاني من أعراض غير معتادة.','123458909965','2025-11-29 22:22:35'),(17,6,'Rawan Magdy','قرص مره',1,NULL,NULL,'','00:25','','دواء \"Rawan Magdy\" هو دواء يُستخدم في فئة معينة من العلاجات. إليك ملخصاً موجزاً عنه:\n\n**فئة العلاج:**  \nيُصنف هذا الدواء ضمن الأدوية المستخدمة لعلاج حالات معينة، ولكن يجب التأكد من الفئة الدقيقة من خلال استشارة الطبيب أو الصيدلي.\n\n**آلية العمل:**  \nيعمل هذا الدواء عن طريق التأثير على العمليات الكيميائية في الجسم، مما يساعد في تخفيف الأعراض أو معالجة الحالة المرضية. \n\n**أهم الاستخدامات:**  \nيُستخدم \"Rawan Magdy\" لعلاج مجموعة من الحالات، مثل [أذكر الاستخدامات الشائعة إذا كانت معروفة، مثل الألم، الالتهابات، إلخ]. \n\n**أبرز التحذيرات:**  \n- يجب عدم استخدامه في حالة وجود حساسية معروفة تجاه مكوناته.\n- يُنصح بعدم تناوله مع أدوية أخرى دون استشارة الطبيب، لتجنب التفاعلات السلبية.\n- يُفضل استشارة الطبيب في حال وجود حالات صحية مزمنة أو تناول أدوية أخرى.\n\n**جرعة مقترحة:**  \nالجرعة المقترحة هي قرص واحد مرة واحدة، ولكن يجب الالتزام بتعليمات الطبيب.\n\nتذكر أن هذه المعلومات لا تغني عن استشارة الطبيب، خاصة في حالات الطوارئ أو إذا كانت لديك أي مخاوف صحية.','123458909965','2025-11-29 22:22:53'),(18,7,'باندول','1',1,NULL,NULL,'','18:59','','**دواء باندول**\n\n**فئة العلاج:**  \nباندول هو دواء ينتمي إلى فئة المسكنات والمخفضات للحرارة.\n\n**آلية العمل:**  \nيعمل باندول عن طريق تثبيط إنزيم معين في الجسم يُعرف باسم \"سيكلوأوكسيجيناز\"، مما يقلل من إنتاج المواد الكيميائية التي تسبب الألم والالتهاب.\n\n**أهم الاستخدامات:**  \n- تخفيف الألم الخفيف إلى المعتدل (مثل الصداع، آلام الأسنان، وآلام العضلات).\n- خفض درجة الحرارة المرتفعة (الحمى).\n\n**أبرز التحذيرات:**  \n- يجب عدم تجاوز الجرعة الموصى بها، حيث إن الجرعات العالية قد تؤدي إلى مشاكل في الكبد.\n- يُنصح بعدم استخدامه لفترات طويلة دون استشارة الطبيب.\n- يجب الحذر في حالة وجود مشاكل صحية سابقة مثل أمراض الكبد أو الكلى.\n\n**ملاحظة:**  \nهذه المعلومات لا تغني عن استشارة الطبيب. يُفضل دائماً استشارة متخصص في حال وجود أي استفسارات أو حالات طبية طارئة.','123458909965','2025-11-30 16:55:11'),(19,6,'Rawan Magdy','1',1,NULL,NULL,'','17:42','','عذرًا، لكن لا أستطيع تقديم معلومات عن دواء محدد باسم \"Rawan Magdy\" لأنه يبدو أنه ليس دواء معروف أو مسجل في المصادر الطبية المتاحة لي حتى أكتوبر 2023. \n\nإذا كان لديك اسم دواء آخر أو معلومات إضافية، سأكون سعيدًا بمساعدتك. تذكر دائمًا أن المعلومات التي أقدمها لا تغني عن استشارة الطبيب، وخاصة في حالات الطوارئ أو عند وجود حالات صحية خاصة. من المهم دائمًا استشارة مختص قبل تناول أي دواء.','123458909965','2025-12-02 15:38:45'),(20,6,'Rawan Magdy','1',1,NULL,NULL,'','18:28','','عذرًا، لكن يبدو أن \"Rawan Magdy\" ليس اسم دواء معروف أو متداول في المعلومات الطبية المتاحة حتى أكتوبر 2023. قد يكون اسمًا تجاريًا أو منتجًا محليًا غير موثق.\n\nلذا، إذا كان لديك اسم دواء آخر أو تفاصيل إضافية، سأكون سعيدًا بمساعدتك في تلخيص المعلومات المتعلقة به. تذكر دائمًا أن المعلومات التي أقدمها لا تغني عن استشارة الطبيب، خاصة في حالات الطوارئ أو عند وجود حالات صحية خاصة.','123458909965','2025-12-02 16:24:11');
